// Auto-generated by r2factor. Manual edits will be overwritten on next split.

use super::EDIT_STATES;
use super::FOCUS_HANDLES;
use super::TEXT_ORIGINS;
use gpui::Keystroke;

const MAX_THREAD_LOCAL_INPUT_STATES: usize = 1000;

/// Evict oldest entries if thread-local storage exceeds maximum size.
/// This prevents unbounded memory growth when cleanup functions are not called.
/// Returns the number of entries evicted from each map.
fn trim_thread_local_storage() -> (usize, usize, usize) {
    let mut focus_evicted = 0;
    let mut edit_evicted = 0;
    let mut origins_evicted = 0;

    FOCUS_HANDLES.with(|handles| {
        let mut handles = handles.borrow_mut();
        while handles.len() > MAX_THREAD_LOCAL_INPUT_STATES {
            if let Some(key) = handles.keys().next().cloned() {
                handles.remove(&key);
                focus_evicted += 1;
            }
        }
    });

    EDIT_STATES.with(|states| {
        let mut states = states.borrow_mut();
        while states.len() > MAX_THREAD_LOCAL_INPUT_STATES {
            if let Some(key) = states.keys().next().cloned() {
                states.remove(&key);
                edit_evicted += 1;
            }
        }
    });

    TEXT_ORIGINS.with(|origins| {
        let mut origins = origins.borrow_mut();
        while origins.len() > MAX_THREAD_LOCAL_INPUT_STATES {
            if let Some(key) = origins.keys().next().cloned() {
                origins.remove(&key);
                origins_evicted += 1;
            }
        }
    });

    (focus_evicted, edit_evicted, origins_evicted)
}

/// Convert a keystroke to an insertable character, explicitly handling the
/// space key so it works even when GPUI reports `key_char == None`.
pub(super) fn keystroke_to_char(keystroke: &Keystroke) -> Option<char> {
    if keystroke.key == "space" || keystroke.key == " " {
        Some(' ')
    } else {
        keystroke.key_char.as_ref().and_then(|s| s.chars().next())
    }
}

/// Returns true if any `Input` component is currently in editing mode.
/// Useful for parent views that need to suppress keybindings during text entry.
pub fn is_input_editing() -> bool {
    EDIT_STATES.with(|states| states.borrow().values().any(|state| state.borrow().editing))
}

/// Get the current count of stored input states.
///
/// Useful for debugging memory leaks. If this number grows beyond
/// MAX_THREAD_LOCAL_INPUT_STATES, older entries will be automatically evicted.
///
/// # Returns
/// A tuple of (focus_handle_count, edit_state_count)
pub fn input_state_count() -> (usize, usize, usize) {
    let _ = trim_thread_local_storage();
    let focus_count = FOCUS_HANDLES.with(|handles| handles.borrow().len());
    let edit_count = EDIT_STATES.with(|states| states.borrow().len());
    let origins_count = TEXT_ORIGINS.with(|origins| origins.borrow().len());
    (focus_count, edit_count, origins_count)
}

/// Clear all input states.
///
/// This removes all thread-local state for all Input components.
/// Use with caution - this will reset all input editing state.
pub fn clear_all_input_states() {
    FOCUS_HANDLES.with(|handles| {
        handles.borrow_mut().clear();
    });
    EDIT_STATES.with(|states| {
        states.borrow_mut().clear();
    });
}

#[cfg(test)]
mod tests {
    use super::{
        EDIT_STATES, MAX_THREAD_LOCAL_INPUT_STATES, TEXT_ORIGINS, clear_all_input_states,
        input_state_count, is_input_editing, keystroke_to_char, trim_thread_local_storage,
    };
    use gpui::{ElementId, Keystroke, Modifiers, SharedString};
    use std::cell::RefCell;
    use std::rc::Rc;

    #[test]
    fn test_keystroke_to_char_space() {
        let ks = Keystroke {
            key: "space".into(),
            key_char: None,
            modifiers: Modifiers::default(),
        };
        assert_eq!(keystroke_to_char(&ks), Some(' '));
    }

    #[test]
    fn test_text_origins_trimmed() {
        // Fill TEXT_ORIGINS beyond the limit
        TEXT_ORIGINS.with(|origins| {
            let mut origins = origins.borrow_mut();
            origins.clear();
            for i in 0..=MAX_THREAD_LOCAL_INPUT_STATES {
                origins.insert(
                    ElementId::Name(SharedString::from(format!("origin-{}", i))),
                    i as f32,
                );
            }
        });

        let (_, _, evicted) = trim_thread_local_storage();
        assert!(evicted > 0, "TEXT_ORIGINS should have been trimmed");

        let count = TEXT_ORIGINS.with(|origins| origins.borrow().len());
        assert!(
            count <= MAX_THREAD_LOCAL_INPUT_STATES,
            "TEXT_ORIGINS count {} should be <= {}",
            count,
            MAX_THREAD_LOCAL_INPUT_STATES
        );
    }

    #[test]
    fn keystroke_to_char_regular_key() {
        let ks = Keystroke {
            key: "a".into(),
            key_char: Some("a".into()),
            modifiers: Modifiers::default(),
        };
        assert_eq!(keystroke_to_char(&ks), Some('a'));
    }

    #[test]
    fn is_input_editing_reflects_state() {
        clear_all_input_states();
        assert!(!is_input_editing());

        EDIT_STATES.with(|states| {
            let mut states = states.borrow_mut();
            states.insert(
                ElementId::Name(SharedString::from("test-edit")),
                Rc::new(RefCell::new(super::super::EditState::new("x"))),
            );
        });
        assert!(is_input_editing());
        clear_all_input_states();
    }

    #[test]
    fn input_state_count_trims_all_maps() {
        clear_all_input_states();
        TEXT_ORIGINS.with(|origins| {
            origins.borrow_mut().insert(
                ElementId::Name(SharedString::from("count-test")),
                42.0,
            );
        });
        let (focus, edit, origins) = input_state_count();
        assert_eq!(focus, 0);
        assert_eq!(edit, 0);
        assert_eq!(origins, 1);
        clear_all_input_states();
    }

}
